import path from 'node:path';
import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { Pool, type PoolConfig } from 'pg';
import * as schema from './schema';

export { schema };
export * from './schema';
export type { Pool } from 'pg';
export { and, asc, desc, eq, gt, gte, inArray, isNull, lt, or, sql } from 'drizzle-orm';

export type Database = NodePgDatabase<typeof schema>;

/** Folder with the SQL migrations generated by drizzle-kit. */
export const MIGRATIONS_FOLDER = path.resolve(__dirname, '../migrations');

/** Postgres connection pool with sane defaults; fail fast instead of hanging when the DB is down. */
export function createPool(connectionString: string, options: PoolConfig = {}): Pool {
  return new Pool({
    connectionString,
    max: 10,
    connectionTimeoutMillis: 3_000,
    idleTimeoutMillis: 30_000,
    ...options,
  });
}

/** Typed Drizzle client on top of a pool. Every tenant-owned query must filter by tenant_id. */
export function createDb(pool: Pool): Database {
  return drizzle(pool, { schema });
}

/** Apply all pending migrations. Returns the installed pgvector version (or null). */
export async function runMigrations(connectionString: string): Promise<string | null> {
  const pool = createPool(connectionString, { max: 1 });
  try {
    await migrate(drizzle(pool), { migrationsFolder: MIGRATIONS_FOLDER });
    const { rows } = await pool.query<{ extversion: string }>(
      "select extversion from pg_extension where extname = 'vector'",
    );
    return rows[0]?.extversion ?? null;
  } finally {
    await pool.end();
  }
}
